INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_GANTZ_EARLY_GREEK_MYTH','secondary scholarship','Timothy Gantz, Early Greek Myth: A Guide to Literary and Artistic Sources (Johns Hopkins University Press, 1993)','Comparative source-critical treatment of the Typhon/Echidna monster genealogy and its variants across early Greek poetry and art')
INSERT INTO _e VALUES
 ('ENT_MON_ECHIDNA','Echidna','Monster','Chthonic monster','Greek','Monsters; chthonic generation','B','The half-woman, half-serpent ''mother of monsters''; mate of Typhon and dam of the Greek monster brood. Attested Hesiod, Theogony 295-332 (esp. 304-305 description); Apollodorus 2.1.2. Genealogical hub previously missing from the DB.'),
 ('ENT_MON_ORTHRUS','Orthrus','Monster','Guardian beast','Greek','Monsters; guardian beasts','B','Two-headed hound of Geryon, son of Typhon and Echidna, slain by Heracles; sire (with the Chimera) of the Sphinx and Nemean Lion in Hesiod''s construal. Attested Hesiod, Theogony 309-327; Apollodorus 2.5.10.'),
 ('ENT_MON_SPHINX','Sphinx','Monster','Chthonic monster','Greek','Monsters; riddle/death','B','The Theban Sphinx (Phix), winged lion-bodied woman who posed the riddle; child of Orthrus and the Chimera (Hesiod) or of Typhon/Echidna. Attested Hesiod, Theogony 326-329; Apollodorus 3.5.8. Distinct from the Egyptian sphinx.'),
 ('ENT_MON_HARPIES','Harpies','Monster','Monster collective','Greek','Monsters; storm-winds; snatching','B','Collective of winged storm-spirits (Aello, Ocypete, Celaeno), daughters of Thaumas and Electra, ''snatchers'' who tormented Phineus. Attested Hesiod, Theogony 265-269; Apollodorus 1.9.21. Collective entity.'),
 ('ENT_MON_SIRENS','Sirens','Monster','Monster collective','Greek','Monsters; deadly song','B','Collective of bird-bodied singing maidens whose song lured sailors to death; encountered by Odysseus. Attested Homer, Odyssey 12.39-54, 165-200; Apollodorus E7.18-19. Collective entity.'),
 ('ENT_MON_STYMPHALIAN_BIRDS','Stymphalian Birds','Monster','Monster collective','Greek','Monsters; man-eating birds','B','Man-eating bronze-beaked birds of Lake Stymphalia driven off by Heracles in his sixth labour. Attested Apollodorus 2.5.6; Pausanias 8.22.4. Collective entity.'),
 ('ENT_MON_GRAEAE','Graeae','Monster','Monster collective','Greek','Monsters; old age; prophecy','B','Grey-haired sisters (Deino, Enyo, Pemphredo) sharing one eye and one tooth, daughters of Phorcys and Ceto; coerced by Perseus. Attested Hesiod, Theogony 270-273; Apollodorus 2.4.2. Collective entity.'),
 ('ENT_MON_HECATONCHEIRES','Hecatoncheires','Monster','Primordial monster collective','Greek','Monsters; primordial force','B','The hundred-handed, fifty-headed giants Cottus, Briareus and Gyges, sons of Ouranos and Gaia; allies of Zeus against the Titans and jailers of the imprisoned Titans. Attested Hesiod, Theogony 147-153, 617-735. Collective entity.'),
 ('ENT_MON_GIGANTES','Gigantes','Monster','Primordial monster collective','Greek','Monsters; Gigantomachy','B','Earth-born giants sprung from Gaia (from the blood of Ouranos) who warred on the Olympians in the Gigantomachy. Attested Hesiod, Theogony 183-186; Apollodorus 1.6.1-2. Collective entity.'),
 ('ENT_MON_NIDHOGGR','Níðhöggr','Monster','Chthonic serpent','Germanic/Norse','Monsters; corpse-serpent; world-tree','B','Corpse-devouring dragon-serpent that gnaws the root of Yggdrasil from below in Niflheim/Náströnd. Attested Poetic Edda, Völuspá 39, 66 and Grímnismál 32, 35; Snorri, Prose Edda (Gylfaginning). Norse functional cognate of the Greek chthonic monster-serpent.');
